import type { Metadata } from "next";
import { SITE_NAME } from "@/config";

/**
 * Social images in public/, generated by `npm run assets` in HunterX-Mobile.
 * Page-level openGraph/twitter objects replace the parent's, so they are set
 * explicitly on every page.
 */
const SOCIAL_ALT = "HunterX: Level up your real life";

export const OG_IMAGE = {
  url: "/og-image.png",
  width: 1200,
  height: 630,
  alt: SOCIAL_ALT,
};

export const TWITTER_IMAGE = {
  url: "/twitter-image.png",
  width: 1200,
  height: 600,
  alt: SOCIAL_ALT,
};

type PageMetadataInput = {
  title: string;
  description: string;
  /** Path starting with "/", resolved against metadataBase for the canonical URL. */
  path: string;
  noIndex?: boolean;
  /** Use the title as-is, without the "| HunterX" suffix from the layout. */
  absoluteTitle?: boolean;
};

/**
 * Builds consistent per-page metadata: canonical URL, Open Graph and Twitter
 * card with the shared social image.
 */
export function pageMetadata({
  title,
  description,
  path,
  noIndex = false,
  absoluteTitle = false,
}: PageMetadataInput): Metadata {
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_IN",
      url: path,
      title,
      description,
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [TWITTER_IMAGE],
    },
    ...(noIndex && { robots: { index: false, follow: false } }),
  };
}
